package com.crm.customer.entity;import jakarta.persistence.*;import lombok.Data;import java.time.LocalDateTime;
@Entity @Table(name="client_case_messages") @Data public class ClientCaseMessage {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="case_id",nullable=false,updatable=false) private Long caseId;@Column(name="request_id",nullable=false,unique=true,length=36,updatable=false) private String requestId;@Column(nullable=false,length=4000,updatable=false) private String body;@Column(name="sender_kind",nullable=false,length=10,updatable=false) private String senderKind;@Column(name="author_id",nullable=false,updatable=false) private Long authorId;@Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}}
